const inputs = $('Set Inputs').item.json;

const body = {
  model: 'sonar-pro',
  messages: [
    {
      role: 'system',
      content: 'You are a geopolitical and markets intelligence research assistant. Return structured, dated, source-cited output only. For every claim flag as [confirmed], [likely], or [unconfirmed]. Prioritize: official documents > laws/filings > IMF/BIS/World Bank > market research > think tanks > media. Never speculate without labeling it. Return clean markdown with headers matching the requested sections.'
    },
    {
      role: 'user',
      content: inputs.prompt
    }
  ],
  max_tokens: 6000,
  temperature: 0.1,
  return_citations: true,
  return_related_questions: false,
  search_recency_filter: inputs.recency_filter || 'year'
};

return [{ json: {
  entity: inputs.entity,
  prompt: inputs.prompt,
  recency_filter: inputs.recency_filter,
  requestBody: JSON.stringify(body)
}}];

const fs = require('fs');
const path = require('path');

const buildNode = $('Build Request').item.json;
const apiResponse = $('Perplexity Sonar API').item.json;

const entity = buildNode.entity;
const prompt = buildNode.prompt;
const content = apiResponse.choices?.[0]?.message?.content || 'ERROR: No content returned';
const citations = apiResponse.citations || [];
const model = apiResponse.model || 'sonar-pro';
const tokens = apiResponse.usage?.total_tokens || 'unknown';

const today = new Date().toISOString().split('T')[0];
const entitySlug = entity.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const filename = `${entitySlug}-research-${today}.md`;

const citationBlock = citations.length > 0
  ? citations.map((c, i) => `${i + 1}. ${c}`).join('\n')
  : 'No citations returned by model.';

const rawNote = [
  `# ${entity} — Research Note`,
  `## Internal Research Note — Priority 7 Source`,
  `## Status: hypothesis pending corroboration by Priority 1-4 sources`,
  `## Compiled: ${today}`,
  `## Model: Perplexity ${model} | Tokens: ${tokens}`,
  ``,
  `---`,
  ``,
  content,
  ``,
  `---`,
  ``,
  `## Citations (Perplexity)`,
  ``,
  citationBlock,
  ``,
  `---`,
  ``,
  `## Original Prompt`,
  ``,
  prompt
].join('\n');

const targetDir = '/wiki/raw/internal-notes';
const targetPath = path.join(targetDir, filename);

fs.mkdirSync(targetDir, { recursive: true });
fs.writeFileSync(targetPath, rawNote, 'utf-8');
const bytes = fs.statSync(targetPath).size;

return [{ json: {
  status: 'success',
  entity,
  filename,
  container_path: targetPath,
  host_path: `C:\\Users\\ruben\\source\\repos\\iPM-WIKI\\raw\\internal-notes\\${filename}`,
  bytes,
  tokens,
  next_step: `Tell Claude: ingest raw/internal-notes/${filename}`
}}];
